import { prisma } from "@/lib/prisma"
import type { DocumentReportsQueryResult, SourceMeta, WorkflowStepMeta } from "../types"
import { buildDocumentReportsQuery } from "./query-builders"

// ============================================================================
// Queries
// ============================================================================

export async function queryWorkflowSteps(): Promise<WorkflowStepMeta[]> {
  return prisma.workflowStep.findMany({
    select: { id: true, name: true, stepType: true },
  })
}

export async function queryAvailableSources(): Promise<SourceMeta[]> {
  return prisma.source.findMany({
    select: { sourceName: true },
    distinct: ["sourceName"],
    orderBy: { sourceName: "asc" },
  })
}

export async function queryDocumentReports(args: {
  dateRange?: { from: Date; to: Date }
  sourceName?: string
  workflowId?: string
}): Promise<DocumentReportsQueryResult[]> {
  return prisma.$queryRaw<DocumentReportsQueryResult[]>(buildDocumentReportsQuery(args))
}

