"use server"

import { privilegedAction } from "@/lib/server-actions"
import { documentReportsQuerySchema } from "./schemas"
import { fetchDocumentReportsData } from "./service"
import { exportDocumentReportsToExcelService } from "./export-service"

export const getDocumentReports = privilegedAction
  .inputSchema(documentReportsQuerySchema)
  .action(async ({ parsedInput }) => {
    const { dateRange, sourceName, workflowId } = parsedInput || {}
    const data = await fetchDocumentReportsData({ dateRange, sourceName, workflowId })
    return { data }
  })

export const exportDocumentReportsToExcel = privilegedAction
  .inputSchema(documentReportsQuerySchema)
  .action(async ({ parsedInput }) => {
    const { dateRange, sourceName, workflowId } = parsedInput || {}
    return exportDocumentReportsToExcelService({ dateRange, sourceName, workflowId })
  })
